193	    /// The service has already converted Vision bounds to a top-left origin.
194	    /// Apply only the displayed image's aspect-fit scale and letterbox offsets.
195	    private func faceRect(_ bounds: ReferenceFaceBounds, imageSize: CGSize, container: CGSize) -> CGRect {
196	        let scale = min(container.width / imageSize.width, container.height / imageSize.height)
197	        let width = imageSize.width * scale, height = imageSize.height * scale
198	        return CGRect(x: (container.width - width) / 2 + CGFloat(bounds.x) * width,
199	                      y: (container.height - height) / 2 + CGFloat(bounds.y) * height,
200	                      width: CGFloat(bounds.width) * width, height: CGFloat(bounds.height) * height)
201	    }
