389	    private func rigBasis(_ basis: GuidedRigBasis) -> some View {
390	        let usesAnalysisDirection = acceptedAnalysisDirection == basis.observations.direction
391	        let observed = GuidedRigBasis.Cue.allCases.filter {
392	            basis.provenance(for: $0) == .userObservation && !($0 == .direction && usesAnalysisDirection)
393	        }
394	        let observedText = observed.map { cue in
395	            let value: String
396	            switch cue {
397	            case .direction: value = basis.observations.direction.rawValue
398	            case .softness: value = basis.observations.softness.rawValue
399	            case .fill: value = basis.observations.fill.rawValue
400	            case .rim: value = basis.observations.rim.rawValue
401	            }
402	            return "\(cue.rawValue): \(value)"
403	        }.joined(separator: "; ")
404	        let unknownText = basis.unobservedCues.map(\.rawValue).joined(separator: ", ")
405	        let distance = StudioNumericInput.formattedValue(basis.keyDistanceMeters)
406	        let azimuth = StudioNumericInput.formattedValue(basis.keyAzimuthDegrees)
407	        let elevation = StudioNumericInput.formattedValue(basis.keyElevationDegrees)
408	        let lux = StudioNumericInput.formattedValue(basis.keyIlluminanceLux)
409	        let kelvin = StudioNumericInput.formattedValue(basis.lightKelvin)
410	        return VStack(alignment: .leading, spacing: 6) {
411	            Text("Basis for this rig").font(.subheadline.weight(.semibold))
412	            Text(observedText.isEmpty ? "Your observations — none selected" : "Your observations — \(observedText)")
413	                .accessibilityIdentifier("guidedObservedCues")
414	            if usesAnalysisDirection {
415	                Text("Accepted on-device suggestion — Key side: \(basis.observations.direction.rawValue)")
416	                    .accessibilityIdentifier("guidedSuggestedCues")
417	            }
418	            Text(unknownText.isEmpty ? "No unknown cues. Exact geometry and output are still assumptions."
419	                 : "Assumed cues — \(unknownText)")
420	                .accessibilityIdentifier("guidedAssumedCues")
421	            Text("Chosen starting values — \(distance) m key distance · \(azimuth)° side · \(elevation)° elevation · \(lux) lx key · \(kelvin) K")
422	                .monospacedDigit()
423	                .accessibilityIdentifier("guidedStartingValues")
424	            Text("Angles are camera-relative. Exact geometry, power and color remain starting assumptions for every rig.")
425	                .foregroundStyle(.secondary)
426	        }
427	        .font(.caption)
428	        .frame(maxWidth: .infinity, alignment: .leading)
429	        .padding(.vertical, 4)
