432	    @MainActor private func load(_ item: PhotosPickerItem, token: UUID) {
433	        importTask?.cancel()
434	        importTask = Task {
435	            defer {
436	                if requestID == token { importTask = nil }
437	            }
438	            do {
439	                let transferred = try await item.loadTransferable(type: ReferencePhoto.self)
440	                // A provider may finish after cancellation. Reject its result
441	                // before constructing an obsolete image on the main actor.
442	                guard !Task.isCancelled, requestID == token else { return }
443	                guard let photo = transferred, let image = UIImage(data: photo.png) else {
444	                    throw ReferenceImportError.unreadable
445	                }
446	                guard !Task.isCancelled, requestID == token else { return }
447	                reference = image
448	                tones = photo.tones
449	                observations = .init(); candidates = []; previewID = nil; rigError = nil
450	                confirmApply = false
451	                sizeDescription = "\(photo.width) × \(photo.height) px · session only"
452	                loading = false
453	                startAnalysis(png: photo.png)
454	            } catch is CancellationError {
455	                guard !Task.isCancelled, requestID == token else { return }
456	                loading = false
457	            } catch {
458	                guard !Task.isCancelled, requestID == token else { return }
459	                let detail = (error as? ReferenceImportError)?.errorDescription ??
460	                    "The photo is unavailable. Check Photos or choose another local image."
461	                failure = reference == nil ? detail : "Replacement failed. Your previous photo is still open. \(detail)"
462	                loading = false
463	            }
464	        }
465	    }
