467	    @MainActor private func startAnalysis(png: Data) {
468	        cancelAnalysis()
469	        let token = analysisRequestID
470	        analyzing = true
471	        // Keep PNG bytes only for the service call, never in view state or a project.
472	        analysisTask = Task {
473	            defer {
474	                if analysisRequestID == token {
475	                    analysisTask = nil
476	                    analyzing = false
477	                }
478	            }
479	            do {
480	                let result = try await ReferenceAnalysisService.analyze(png: png)
481	                guard !Task.isCancelled, analysisRequestID == token else { return }
482	                analysis = result
483	            } catch {
484	                guard !Task.isCancelled, analysisRequestID == token else { return }
485	                analysisFailure = "The on-device check could not finish. Choose the key side manually."
486	            }
487	        }
488	    }
