490	    @MainActor private func useSuggestedSide() {
491	        guard let analysis, analysis.support == .supported, !analysis.requiresManualDirection else { return }
492	        acceptedAnalysisDirection = analysis.observations.direction
493	        // Explicit adoption changes only direction; unknown/manual cues remain intact.
494	        observations.direction = analysis.observations.direction
495	    }
