497	    /// Import cancellation is independent: a failed or cancelled replacement keeps
498	    /// the previous photo's result, including any check that is still running.
499	    @MainActor private func cancelAnalysis() {
500	        analysisRequestID = UUID()
501	        analysisTask?.cancel()
502	        analysisTask = nil
503	        analysis = nil
504	        analyzing = false
505	        analysisFailure = nil
506	        acceptedAnalysisDirection = nil
507	    }
508	
509	    /// Cancelling a replacement retains the previous photo and guided work.
510	    /// Only explicit Remove, closing, or applying the rig discards that session.
511	    @MainActor private func cancelImport() {
512	        requestID = UUID()
513	        importTask?.cancel()
514	        importTask = nil
515	        selection = nil
516	        failure = nil
517	        loading = false
518	    }
519	
520	    @MainActor private func clear() {
521	        cancelImport()
522	        cancelAnalysis()
523	        reference = nil
524	        tones = nil
525	        observations = .init(); candidates = []; previewID = nil; rigError = nil
526	        confirmApply = false
527	        sizeDescription = ""
528	    }
529	
530	    @MainActor private func closeSession() {
531	        guard !sessionClosed else { return }
532	        sessionClosed = true
533	        confirmApply = false
534	        clear()
535	    }
