348	/// SwiftUI disappearance also occurs when a nested picker or sheet covers a
349	/// session. Only a completed dismissal of this controller's ancestor releases
350	/// the photos; a cancelled interactive swipe must retain them.
351	@MainActor
352	struct ComparisonSessionDismissalObserver: UIViewControllerRepresentable {
353	    let onDismiss: () -> Void
354	
355	    func makeUIViewController(context: Context) -> Controller {
356	        let controller = Controller()
357	        controller.onDismiss = onDismiss
358	        return controller
359	    }
360	
361	    func updateUIViewController(_ controller: Controller, context: Context) {
362	        controller.onDismiss = onDismiss
363	    }
364	
365	    final class Controller: UIViewController {
366	        var onDismiss: (() -> Void)?
367	        private var dismissalStarted = false
368	
369	        private var ancestorIsBeingDismissed: Bool {
370	            var ancestor: UIViewController? = self
371	            while let current = ancestor {
372	                if current.isBeingDismissed { return true }
373	                ancestor = current.parent
374	            }
375	            return false
376	        }
377	
378	        override func loadView() {
379	            view = UIView(frame: .zero)
380	            view.isUserInteractionEnabled = false
381	        }
382	
383	        override func viewWillDisappear(_ animated: Bool) {
384	            super.viewWillDisappear(animated)
385	            dismissalStarted = ancestorIsBeingDismissed
386	        }
387	
388	        override func viewDidDisappear(_ animated: Bool) {
389	            super.viewDidDisappear(animated)
390	            if dismissalStarted || ancestorIsBeingDismissed { onDismiss?() }
391	            dismissalStarted = false
392	        }
393	
394	        override func viewDidAppear(_ animated: Bool) {
395	            super.viewDidAppear(animated)
396	            dismissalStarted = false
397	        }
398	    }
399	}
