414	/// Each slot owns its task and generation. An obsolete provider completion can
415	/// neither replace an image nor clear the loading state of a newer import.
416	@MainActor
417	private final class ComparisonPhotoSlot: ObservableObject {
418	    @Published private(set) var image: UIImage?
419	    @Published private(set) var isLoading = false
420	    @Published private(set) var failure: String?
421	    private var requestID = UUID()
422	    private var importTask: Task<Void, Never>?
423	
424	    init(image: UIImage? = nil) { self.image = image }
425	
426	    var pixelDescription: String {
427	        guard let image else { return "" }
428	        let width = image.cgImage?.width ?? Int(image.size.width * image.scale)
429	        let height = image.cgImage?.height ?? Int(image.size.height * image.scale)
430	        return "\(width) × \(height) px · session only"
431	    }
432	
433	    func load(_ item: PhotosPickerItem) {
434	        cancelImport()
435	        let token = requestID
436	        isLoading = true
437	        importTask = Task { [weak self] in
438	            defer {
439	                if self?.requestID == token {
440	                    self?.isLoading = false
441	                    self?.importTask = nil
442	                }
443	            }
444	            do {
445	                let transferred = try await item.loadTransferable(type: ReferencePhoto.self)
446	                guard let self, !Task.isCancelled, self.requestID == token else { return }
447	                guard let photo = transferred, let replacement = UIImage(data: photo.png) else {
448	                    throw ReferenceImportError.unreadable
449	                }
450	                guard !Task.isCancelled, self.requestID == token else { return }
451	                self.image = replacement
452	                self.failure = nil
453	            } catch is CancellationError {
454	                // Provider cancellation leaves any previous image intact.
455	            } catch {
456	                guard let self, !Task.isCancelled, self.requestID == token else { return }
457	                let detail = (error as? ReferenceImportError)?.errorDescription ??
458	                    "The photo is unavailable. Check Photos or choose another local image."
459	                self.failure = self.image == nil ? detail :
460	                    "Replacement failed. Your previous photo is still open. \(detail)"
461	            }
462	        }
463	    }
464	
465	    func cancelImport() {
466	        requestID = UUID()
467	        importTask?.cancel()
468	        importTask = nil
469	        isLoading = false
470	        failure = nil
471	    }
472	
473	    func clear() {
474	        cancelImport()
475	        image = nil
476	    }
477	
478	    deinit { importTask?.cancel() }
479	}

