  4	/// Presents the session's current feature without adding a second route owner.
  5	@MainActor
  6	struct StudioFeatureSheets: ViewModifier {
  7	    let session: StudioSession
  8	    let onReferenceApplied: () -> Void
  9	
 10	    func body(content: Content) -> some View {
 11	        content.background {
 12	            if let feature = session.feature {
 13	                let context = feature.context
 14	                Color.clear
 15	                    .sheet(isPresented: presentationBinding(for: context), onDismiss: {
 16	                        session.finishFeature(context)
 17	                    }) {
 18	                        destination(for: feature)
 19	                            .disabled(session.isBusy)
 20	                    }
 21	                    .id(context.id)
 22	            }
 23	        }
 24	    }
 25	
 26	    private func presentationBinding(for context: StudioFeatureContext) -> Binding<Bool> {
 27	        Binding(get: {
 28	            guard let current = session.feature else { return false }
 29	            return current.id == context.id && current.isPresented
 30	        }, set: { presented in
 31	            // A sheet may retire only its own live receipt. A late true write
 32	            // cannot reopen it, and an old dismissal cannot retire a new owner.
 33	            guard !presented else { return }
 34	            session.retireFeature(context)
 35	        })
 36	    }
 37	
 38	    @ViewBuilder
 39	    private func destination(for feature: StudioFeaturePresentation) -> some View {
 40	        let context = feature.context
 41	        switch feature.destination {
 42	        case .reference:
 43	            ReferenceComparisonView(scene: context.scene) { next in
 44	                guard session.applyFeatureScene(next, from: context) else {
 45	                    reportLegacyRejection(from: context)
 46	                    return
 47	                }
 48	                onReferenceApplied()
 49	            }
 50	        case .arrangement:
 51	            SceneArrangementView(scene: context.scene) { next in
 52	                if !session.applyFeatureScene(next, from: context) {
 53	                    reportLegacyRejection(from: context)
 54	                }
 55	            }
 56	        case let .targetLux(lightID):
 57	            if let light = context.scene.lights.first(where: { $0.id == lightID }) {
 58	                LightTargetLuxView(light: light, scene: context.scene) { adjusted in
 59	                    if !session.applyFeatureLight(adjusted, from: context) {
 60	                        reportLegacyRejection(from: context)
 61	                    }
 62	                }
 63	            }
 64	        case .room:
 65	            ManualRoomPlacementView(scene: session.scene,
 66	                onRemove: { session.applyFeatureRoom(nil, from: context) },
 67	                onClose: { session.retireFeature(context) },
 68	                onChange: { session.applyFeatureRoom($0, from: context) })
 69	        case .ar:
 70	            // AR owns its nested manual sheet. Its local close callback must
 71	            // leave this outer receipt active for further room edits.
 72	            ARPlacementView(scene: session.scene,
 73	                onRoomRemove: { session.applyFeatureRoom(nil, from: context) },
 74	                onClose: { session.retireFeature(context) },
 75	                onRoomChange: { session.applyFeatureRoom($0, from: context) })
 76	        }
 77	    }
 78	
 79	    private func reportLegacyRejection(from context: StudioFeatureContext) {
 80	        guard let current = session.feature,
 81	              current.id == context.id, current.isPresented else { return }
 82	        // These Void producers consume their drafts even when admission fails.
 83	        // Feedback must not imply retention or affect a later presentation.
 84	        session.message = "The change was not applied. Reopen this editor and try again."
 85	    }
 86	}

