  6	/// A prepared, immutable snapshot for the system file exporter. Exporting does
  7	/// not save, switch or overwrite a project in the app's library.
  8	struct ProjectBackupFile: FileDocument, Sendable {
  9	    static let suggestedFilename = "Key-and-Fill-project.json"
 10	    static var readableContentTypes: [UTType] { [.json] }
 11	    let data: Data
 12	
 13	    init(project: LightingProjectDocument) throws {
 14	        data = try project.encode()
 15	    }
 16	
 17	    init(configuration: ReadConfiguration) throws {
 18	        guard configuration.file.isRegularFile,
 19	              let contents = configuration.file.regularFileContents else {
 20	            throw ProjectDocumentIO.ImportError.notRegularFile
 21	        }
 22	        // FileDocument supplies an already materialized wrapper. The app's
 23	        // importer uses read(from:) below to bound bytes before loading them.
 24	        _ = try LightingProjectDocument.decode(contents)
 25	        data = contents
 26	    }
