 33	enum ProjectDocumentIO {
 34	    enum ImportError: Error, Equatable, LocalizedError {
 35	        case notRegularFile, unreadable
 36	
 37	        var errorDescription: String? {
 38	            switch self {
 39	            case .notRegularFile:
 40	                return "Choose a regular Key & Fill project file, not a folder or symbolic link."
 41	            case .unreadable:
 42	                return "The selected project file could not be opened. No saved projects have been changed."
 43	            }
 44	        }
 45	    }
 46	
 47	    /// File-provider URLs are accessed only for this operation. Cancellation
 48	    /// propagates to the utility worker and prevents a completed result from
 49	    /// being delivered to an already-cancelled caller.
 50	    static func read(from url: URL) async throws -> LightingProjectDocument {
 51	        try Task.checkCancellation()
 52	        let cancellation = ReadCancellation()
 53	        let worker = Task.detached(priority: .utility) {
 54	            try readFile(from: url, cancellation: cancellation)
 55	        }
 56	        return try await withTaskCancellationHandler {
 57	            let project = try await worker.value
 58	            try Task.checkCancellation()
 59	            return project
 60	        } onCancel: {
 61	            worker.cancel()
 62	            cancellation.cancel()
 63	        }
 64	    }
 65	
 66	    /// Synchronous worker shared with native file tests. It never mutates the
 67	    /// selected file or the project library, and reads at most maximumBytes + 1.
 68	    static func readFile(from url: URL) throws -> LightingProjectDocument {
 69	        try readFile(from: url, cancellation: ReadCancellation())
 70	    }
 71	
 72	    private static func readFile(from url: URL, cancellation: ReadCancellation) throws -> LightingProjectDocument {
 73	        try cancellation.checkCancellation()
 74	        guard url.isFileURL else { throw ImportError.unreadable }
 75	        let scopedAccess = url.startAccessingSecurityScopedResource()
 76	        defer {
 77	            if scopedAccess { url.stopAccessingSecurityScopedResource() }
 78	        }
 79	        // Do not hand a known symlink, directory or FIFO to coordination. A
 80	        // metadata-only preflight can reject those without opening provider
 81	        // content; unavailable metadata still gets the provider's normal path.
 82	        // The descriptor check inside the accessor remains authoritative if
 83	        // the pathname changes after this early check.
 84	        do { try BoundedFileReader.rejectKnownNonRegularFile(at: url) }
 85	        catch let error as BoundedFileReader.ReadError {
 86	            throw importError(for: error)
 87	        }
 88	        // A false scope result is normal for files already inside the sandbox.
 89	        // Keep the scope open while a provider materializes the file and while
 90	        // the accessor reads it. Scope permission alone does not coordinate a
 91	        // provider's outstanding writes or downloads.
 92	        let coordinator = NSFileCoordinator(filePresenter: nil)
 93	        try cancellation.install(coordinator)
 94	        defer { cancellation.finish() }
 95	        try cancellation.checkCancellation()
 96	        var coordinationError: NSError?
 97	        var result: Result<LightingProjectDocument, Error>?
 98	        coordinator.coordinate(readingItemAt: url, options: [], error: &coordinationError) { coordinatedURL in
 99	            result = Result {
100	                try cancellation.checkCancellation()
101	                // The provider may have moved the item. Read its supplied URL;
102	                // do not request symbolic-link resolution from the coordinator.
103	                return try readCoordinatedFile(from: coordinatedURL, cancellation: cancellation)
104	            }
105	        }
106	        try cancellation.checkCancellation()
107	        if let coordinationError { throw coordinationError }
108	        guard let result else { throw ImportError.unreadable }
109	        return try result.get()
110	    }
111	
112	    private static func readCoordinatedFile(from url: URL, cancellation: ReadCancellation) throws -> LightingProjectDocument {
113	        let contents: Data
114	        do {
115	            contents = try BoundedFileReader.read(from: url, maximumBytes: LightingProjectDocument.maximumBytes,
116	                                                  checkCancellation: cancellation.checkCancellation)
117	        } catch let error as BoundedFileReader.ReadError {
118	            throw importError(for: error)
119	        }
120	        try cancellation.checkCancellation()
121	        let project = try LightingProjectDocument.decode(contents)
122	        try cancellation.checkCancellation()
123	        return project
124	    }
125	
126	    private static func importError(for error: BoundedFileReader.ReadError) -> Error {
127	        switch error {
128	        case .tooLarge: return LightingProjectDocument.DocumentError.tooLarge
129	        case .notRegularFile: return ImportError.notRegularFile
130	        case .unreadable: return ImportError.unreadable
131	        }
132	    }
133	
134	    /// Only cancel() crosses the coordinator's worker thread; Foundation
135	    /// explicitly permits that method from any thread. The lock protects its
136	    /// lifetime and cancellation arriving before the worker installs it.
137	    private final class ReadCancellation: @unchecked Sendable {
138	        private let lock = NSLock()
139	        private var coordinator: NSFileCoordinator?
140	        private var isCancelled = false
141	
142	        func checkCancellation() throws {
143	            try Task.checkCancellation()
144	            lock.lock()
145	            defer { lock.unlock() }
146	            if isCancelled { throw CancellationError() }
147	        }
148	
149	        func install(_ coordinator: NSFileCoordinator) throws {
150	            lock.lock()
151	            defer { lock.unlock() }
152	            guard !isCancelled else { throw CancellationError() }
153	            self.coordinator = coordinator
154	        }
155	
156	        func cancel() {
157	            lock.lock()
158	            isCancelled = true
159	            let current = coordinator
160	            lock.unlock()
161	            current?.cancel()
162	        }
163	
164	        func finish() {
165	            lock.lock()
166	            coordinator = nil
167	            lock.unlock()
168	        }
169	    }
170	}

