  8	enum ReferenceImportError: LocalizedError, Equatable {
  9	    case tooLarge, unsupported, unreadable
 10	    var errorDescription: String? {
 11	        switch self {
 12	        case .tooLarge: return "Choose a photo under 32 MiB and 100 megapixels."
 13	        case .unsupported: return "Choose a single JPEG, PNG or HEIF still image."
 14	        case .unreadable: return "The selected image could not be read. Try another photo."
