 19	/// Session-only derivative. No asset identifier, source URL, EXIF or GPS is retained.
 20	/// A system-owned temporary file is consumed inside the transfer callback.
 21	struct ReferencePhoto: Transferable, Sendable {
 22	    static let byteLimit = 32 * 1024 * 1024
 23	    static let pixelLimit = 100_000_000
 24	    static let maxEdge = 1600
 25	    let png: Data
 26	    let width: Int
 27	    let height: Int
 28	    let tones: ReferenceTonalSummary?
 29	
 30	    static var transferRepresentation: some TransferRepresentation {
 31	        // Prefer the exact types accepted by the bounded decoder. A provider
 32	        // may also advertise the abstract image type; inspect its actual bytes.
 33	        FileRepresentation(importedContentType: .jpeg) { try Self.read(file: $0.file) }
 34	        FileRepresentation(importedContentType: .png) { try Self.read(file: $0.file) }
 35	        FileRepresentation(importedContentType: .heic) { try Self.read(file: $0.file) }
 36	        FileRepresentation(importedContentType: .heif) { try Self.read(file: $0.file) }
 37	        FileRepresentation(importedContentType: .image) { try Self.read(file: $0.file) }
 38	    }
 39	
 40	    static func read(file: URL) throws -> Self {
 41	        let data: Data
 42	        do {
 43	            // The provider's temporary file is consumed inside its transfer
 44	            // callback. Validate the opened descriptor, not earlier path metadata.
 45	            data = try BoundedFileReader.read(from: file, maximumBytes: byteLimit)
 46	        } catch let error as BoundedFileReader.ReadError {
 47	            switch error {
 48	            case .tooLarge: throw ReferenceImportError.tooLarge
 49	            case .notRegularFile, .unreadable: throw ReferenceImportError.unreadable
 50	            }
 51	        }
 52	        return try sanitize(data)
 53	    }
 54	
 55	    static func sanitize(_ data: Data) throws -> Self {
 56	        try Task.checkCancellation()
 57	        guard data.count <= byteLimit else { throw ReferenceImportError.tooLarge }
 58	        let noCache = [kCGImageSourceShouldCache: false] as CFDictionary
 59	        guard let source = CGImageSourceCreateWithData(data as CFData, noCache),
 60	              CGImageSourceGetStatus(source) == .statusComplete,
 61	              let identifier = CGImageSourceGetType(source) else { throw ReferenceImportError.unreadable }
 62	        let allowed = [UTType.jpeg.identifier, UTType.png.identifier, UTType.heic.identifier, UTType.heif.identifier]
 63	        guard allowed.contains(identifier as String), CGImageSourceGetCount(source) == 1 else {
 64	            throw ReferenceImportError.unsupported
 65	        }
 66	        guard let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, noCache) as? [String: Any],
 67	              let w = (properties[kCGImagePropertyPixelWidth as String] as? NSNumber)?.intValue,
 68	              let h = (properties[kCGImagePropertyPixelHeight as String] as? NSNumber)?.intValue,
 69	              w > 0, h > 0 else { throw ReferenceImportError.unreadable }
 70	        guard w <= pixelLimit, h <= pixelLimit / w else { throw ReferenceImportError.tooLarge }
 71	        let options: [CFString: Any] = [
 72	            kCGImageSourceCreateThumbnailFromImageAlways: true,
 73	            kCGImageSourceCreateThumbnailWithTransform: true,
 74	            kCGImageSourceThumbnailMaxPixelSize: maxEdge,
 75	            kCGImageSourceShouldCacheImmediately: true
 76	        ]
 77	        try Task.checkCancellation()
 78	        guard let thumb = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary),
 79	              thumb.width > 0, thumb.height > 0,
 80	              max(thumb.width, thumb.height) <= maxEdge,
 81	              let space = CGColorSpace(name: CGColorSpace.sRGB),
 82	              let canvas = CGContext(data: nil, width: thumb.width, height: thumb.height,
 83	                                     bitsPerComponent: 8, bytesPerRow: thumb.width * 4,
 84	                                     space: space, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
 85	        else { throw ReferenceImportError.unreadable }
 86	        guard CGImageSourceGetStatusAtIndex(source, 0) == .statusComplete else {
 87	            throw ReferenceImportError.unreadable
 88	        }
 89	        try Task.checkCancellation()
 90	        // Draw only pixels into a new sRGB bitmap; never propagate source metadata.
 91	        canvas.draw(thumb, in: CGRect(x: 0, y: 0, width: CGFloat(thumb.width), height: CGFloat(thumb.height)))
 92	        guard let pixels = canvas.makeImage() else { throw ReferenceImportError.unreadable }
 93	        let encoded = NSMutableData()
 94	        guard let destination = CGImageDestinationCreateWithData(encoded as CFMutableData, UTType.png.identifier as CFString, 1, nil)
 95	        else { throw ReferenceImportError.unreadable }
 96	        CGImageDestinationAddImage(destination, pixels, nil)
 97	        guard CGImageDestinationFinalize(destination), encoded.length <= byteLimit else {
 98	            throw ReferenceImportError.unreadable
 99	        }
100	        try Task.checkCancellation()
101	        // ImageIO may emit ancillary metadata even for a newly drawn bitmap.
102	        // Retain only structural, transparency and color-management PNG chunks.
103	        let clean: Data
104	        do { clean = try ReferencePNG.metadataFree(encoded as Data, maximumBytes: byteLimit) }
105	        catch { throw ReferenceImportError.unreadable }
106	        try Task.checkCancellation()
107	        let tones = Self.measure(pixels)
108	        // Cancellation can arrive during either synchronous filtering or drawing.
109	        // Do not publish a completed derivative from a cancelled import.
110	        try Task.checkCancellation()
111	        return Self(png: clean, width: pixels.width, height: pixels.height, tones: tones)
112	    }
113	
114	    /// Fixed, aspect-preserving thumbnail, explicit RGBA8 byte order. No source
115	    /// file or pixels are retained by the statistics value.
116	    private static func measure(_ image: CGImage) -> ReferenceTonalSummary? {
117	        let scale = min(1, 128.0 / Double(max(image.width, image.height)))
118	        let width = max(1, Int((Double(image.width) * scale).rounded()))
119	        let height = max(1, Int((Double(image.height) * scale).rounded()))
120	        guard let space = CGColorSpace(name: CGColorSpace.sRGB) else { return nil }
121	        var bytes = [UInt8](repeating: 0, count: width * height * 4)
122	        let drawn = bytes.withUnsafeMutableBytes { buffer -> Bool in
123	            guard let context = CGContext(data: buffer.baseAddress, width: width, height: height,
124	                    bitsPerComponent: 8, bytesPerRow: width * 4, space: space,
125	                    bitmapInfo: CGBitmapInfo.byteOrder32Big.rawValue | CGImageAlphaInfo.premultipliedLast.rawValue) else { return false }
126	            context.interpolationQuality = .medium
127	            context.draw(image, in: CGRect(x: 0, y: 0, width: CGFloat(width), height: CGFloat(height)))
128	            return true
129	        }
130	        return drawn ? ReferenceTonalSummary(rgba: bytes) : nil
131	    }
132	}
