 33	    let support: ReferenceAnalysisSupport
 34	    let observations: ReferenceObservations
 35	    let explanation: String
 36	    let limitations: [String]
 37	    let faceBounds: ReferenceFaceBounds?
 38	    let measurements: ReferenceFaceMeasurements?
 39	
