 43	/// Session-only, on-device analysis of the upright, sanitized PNG in ReferencePhoto.
 44	/// Only Sendable values cross the task boundary. Pixels and Vision observations are
 45	/// released after the request; nothing is saved, logged, identified, or uploaded.
 46	enum ReferenceAnalysisService {
 47	    private static let maximumBytes = 32 * 1024 * 1024
 48	    private static let maximumSourceEdge = 1600
 49	    private static let maximumAnalysisEdge = 640
 50	    private static let limitations = [
 51	        "This is a tentative cue from image brightness, not an exact reconstruction or a calibrated confidence score.",
 52	        "Skin reflectance, makeup, hair, pose, reflections, exposure and editing can change the apparent key side.",
 53	        "Balanced face brightness cannot distinguish a centered key from several lights. Shadow softness, fill and rim remain for you to judge.",
 54	        "Image luminance does not measure lamp power, lux, light distance, modifier size or color temperature. Any rig settings are starting assumptions."
 55	    ]
 56	
 57	    /// Invalid or unsuitable images return an explicit manual-fallback result.
 58	    /// Cancellation throws CancellationError and never returns a stale suggestion.
 59	    nonisolated static func analyze(png: Data) async throws -> ReferenceAnalysisResult {
 60	        try Task.checkCancellation()
 61	        let cancellation = RequestCancellation()
 62	        let worker = Task.detached(priority: .userInitiated) {
 63	            try autoreleasepool {
 64	                try analyzePixels(png, cancellation: cancellation)
 65	            }
 66	        }
 67	        return try await withTaskCancellationHandler {
 68	            let result = try await worker.value
 69	            try Task.checkCancellation()
 70	            return result
 71	        } onCancel: {
 72	            worker.cancel()
 73	            cancellation.cancel()
 74	        }
 75	    }
