 77	    private static func result(_ support: ReferenceAnalysisSupport, _ explanation: String,
 78	                               bounds: ReferenceFaceBounds? = nil,
 79	                               measurements: ReferenceFaceMeasurements? = nil,
 80	                               direction: ReferenceObservations.Direction = .unknown) -> ReferenceAnalysisResult {
 81	        ReferenceAnalysisResult(support: support,
 82	            observations: ReferenceObservations(direction: direction), explanation: explanation,
 83	            limitations: limitations, faceBounds: bounds, measurements: measurements)
 84	    }
