 86	    private static func analyzePixels(_ png: Data, cancellation: RequestCancellation) throws -> ReferenceAnalysisResult {
 87	        try Task.checkCancellation()
 88	        guard !png.isEmpty, png.count <= maximumBytes else {
 89	            return result(.unsupported, "The reference is empty or exceeds the analysis size limit. Choose another photo or set the key side manually.")
 90	        }
 91	        let noCache = [kCGImageSourceShouldCache: false] as CFDictionary
 92	        guard let source = CGImageSourceCreateWithData(png as CFData, noCache),
 93	              CGImageSourceGetStatus(source) == .statusComplete,
 94	              let type = CGImageSourceGetType(source), type as String == UTType.png.identifier,
 95	              CGImageSourceGetCount(source) == 1,
 96	              let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, noCache) as? [String: Any],
 97	              let widthNumber = properties[kCGImagePropertyPixelWidth as String] as? NSNumber,
 98	              let heightNumber = properties[kCGImagePropertyPixelHeight as String] as? NSNumber else {
 99	            return result(.unsupported, "The sanitized reference could not be read. Import the photo again or set the key side manually.")
100	        }
101	        // Check numeric values before converting to Int or allocating any pixels.
102	        let sourceWidth = widthNumber.doubleValue, sourceHeight = heightNumber.doubleValue
103	        let orientation = (properties[kCGImagePropertyOrientation as String] as? NSNumber)?.intValue ?? 1
104	        guard sourceWidth.isFinite, sourceHeight.isFinite,
105	              sourceWidth >= 1, sourceHeight >= 1,
106	              sourceWidth <= Double(maximumSourceEdge), sourceHeight <= Double(maximumSourceEdge),
107	              sourceWidth.rounded() == sourceWidth, sourceHeight.rounded() == sourceHeight,
108	              orientation == 1 else {
109	            return result(.unsupported, "Analysis needs an upright, bounded reference image. Import it again or choose the key side manually.")
110	        }
111	        let options: [CFString: Any] = [
112	            kCGImageSourceCreateThumbnailFromImageAlways: true,
113	            kCGImageSourceCreateThumbnailWithTransform: true,
114	            kCGImageSourceThumbnailMaxPixelSize: maximumAnalysisEdge,
115	            kCGImageSourceShouldCacheImmediately: true
116	        ]
117	        guard let image = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary),
118	              CGImageSourceGetStatusAtIndex(source, 0) == .statusComplete,
119	              image.width > 0, image.height > 0,
120	              image.width <= maximumAnalysisEdge, image.height <= maximumAnalysisEdge else {
121	            return result(.unsupported, "The reference could not be decoded within the analysis limits. Choose another photo or use manual guidance.")
122	        }
123	        try Task.checkCancellation()
124	
125	        // Apple Vision detects rectangles and pose only; no face recognition or identity model.
126	        let request = VNDetectFaceRectanglesRequest()
127	        request.revision = VNDetectFaceRectanglesRequestRevision3
128	        cancellation.register(request)
129	        defer { cancellation.clear() }
130	        try Task.checkCancellation()
131	        do {
132	            try VNImageRequestHandler(cgImage: image, orientation: .up, options: [:]).perform([request])
133	        } catch {
134	            try Task.checkCancellation()
135	            return result(.unsupported, "Face detection could not finish on this photo. You can still choose the lighting cues manually.")
136	        }
137	        try Task.checkCancellation()
138	        let faces = request.results ?? []
139	        guard !faces.isEmpty else {
140	            return result(.unsupported, "No supported face was detected. Use a clear portrait with one visible face, or choose the key side manually.")
141	        }
142	        guard faces.count == 1, let face = faces.first else {
143	            return result(.unsupported, "More than one face was detected. Choose a single-person portrait or set the key side manually.")
144	        }
145	        let box = face.boundingBox
146	        let components = [Double(box.minX), Double(box.minY), Double(box.width), Double(box.height)]
147	        guard components.allSatisfy(\.isFinite), box.width > 0, box.height > 0,
148	              box.minX >= 0, box.minY >= 0, box.maxX <= 1, box.maxY <= 1 else {
149	            return result(.unsupported, "The face bounds are incomplete. Try a portrait showing the whole face or use manual guidance.")
150	        }
151	        // Vision's origin is lower-left; CGImage cropping uses image rows from the top.
152	        let bounds = ReferenceFaceBounds(x: Double(box.minX), y: 1 - Double(box.maxY),
153	                                         width: Double(box.width), height: Double(box.height))
154	        guard face.confidence.isFinite, face.confidence >= 0.75 else {
155	            return result(.ambiguous, "The face was not detected clearly enough for a key-side suggestion. Choose the key side manually.", bounds: bounds)
156	        }
157	        guard bounds.width * Double(image.width) >= 48,
158	              bounds.height * Double(image.height) >= 48,
159	              bounds.width * bounds.height >= 0.015 else {
160	            return result(.unsupported, "The face is too small for reliable regional sampling. Use a closer portrait or choose the key side manually.", bounds: bounds)
161	        }
162	        guard bounds.x > 0.01, bounds.y > 0.01,
163	              bounds.x + bounds.width < 0.99, bounds.y + bounds.height < 0.99 else {
164	            return result(.unsupported, "The face touches the image edge and may be cropped. Use a complete face or choose the key side manually.", bounds: bounds)
165	        }
166	        guard let yaw = face.yaw?.doubleValue, let roll = face.roll?.doubleValue,
167	              let pitch = face.pitch?.doubleValue,
168	              yaw.isFinite, roll.isFinite, pitch.isFinite else {
169	            return result(.ambiguous, "The face orientation could not be established. Choose the key side manually.", bounds: bounds)
170	        }
171	        guard abs(yaw) <= 0.35, abs(roll) <= 0.26, abs(pitch) <= 0.35 else {
172	            return result(.unsupported, "The face is turned or tilted too far for this comparison. Use a mostly frontal portrait or choose the key side manually.", bounds: bounds)
173	        }
174	
175	        // Three matching interior bands avoid the hairline, face outline and nose.
176	        // Crop first, then sample each entire patch: no bitmap row-origin assumption
177	        // is needed when comparing left/right or checking consistency across bands.
178	        var left: [PatchStatistics] = [], right: [PatchStatistics] = []
179	        for top in [0.25, 0.40, 0.55] {
180	            try Task.checkCancellation()
181	            guard let l = sample(image, bounds: bounds, x: 0.18, y: top),
182	                  let r = sample(image, bounds: bounds, x: 0.57, y: top) else {
183	                return result(.unsupported, "The face regions could not be sampled. Choose another photo or set the key side manually.", bounds: bounds)
184	            }
185	            left.append(l); right.append(r)
186	        }
187	        let patches = left + right
188	        guard patches.allSatisfy({ $0.opaqueFraction >= 0.95 && $0.count >= 24 }) else {
189	            return result(.unsupported, "The face contains transparent or missing pixels. Use an opaque portrait or set the key side manually.", bounds: bounds)
190	        }
191	        let leftMean = left.map(\.luminance).reduce(0, +) / 3
192	        let rightMean = right.map(\.luminance).reduce(0, +) / 3
193	        let sampledPixelCount = patches.map(\.count).reduce(0, +)
194	        // Patches can contain different numbers of opaque samples after cropping
195	        // and downsampling; a pixel fraction must weight their counts accordingly.
196	        let clipped = patches.reduce(0.0) { $0 + $1.clippedFraction * Double($1.count) }
197	            / Double(sampledPixelCount)
198	        let denominator = leftMean + rightMean
199	        let asymmetry = denominator > 0 ? (leftMean - rightMean) / denominator : 0
200	        let measurements = ReferenceFaceMeasurements(leftLuminance: leftMean, rightLuminance: rightMean,
201	            asymmetry: asymmetry, clippedFraction: clipped,
202	            sampledPixelCount: sampledPixelCount)
203	        guard [leftMean, rightMean, clipped, asymmetry].allSatisfy(\.isFinite) else {
204	            return result(.unsupported, "The brightness comparison was invalid. Choose the key side manually.", bounds: bounds)
205	        }
206	        guard clipped < 0.20, patches.allSatisfy({ $0.clippedFraction < 0.35 }),
207	              denominator / 2 >= 0.015, denominator / 2 <= 0.90 else {
208	            return result(.unsupported, "The sampled face regions are too dark or contain too many near-limit color values for this comparison. Try another exposure or choose the key side manually.", bounds: bounds, measurements: measurements)
209	        }
210	        let sign = asymmetry >= 0 ? 1.0 : -1.0
211	        let consistent = zip(left, right).allSatisfy { l, r in
212	            let total = l.luminance + r.luminance
213	            return total > 0 && sign * (l.luminance - r.luminance) / total >= 0.08
214	        }
215	        // Engineering guardrails, not learned/calibrated probabilities. A symmetrical
216	        // image is deliberately not labeled as a centered lamp or balanced fill.
217	        guard abs(asymmetry) >= 0.22, abs(leftMean - rightMean) >= 0.04, consistent else {
218	            return result(.ambiguous, "Face brightness is too similar or inconsistent across regions to suggest a key side. A centered key and multiple lights can look similar; choose the side manually.", bounds: bounds, measurements: measurements)
219	        }
220	        try Task.checkCancellation()
221	        let direction: ReferenceObservations.Direction = asymmetry > 0 ? .left : .right
222	        let side = asymmetry > 0 ? "image left" : "image right"
223	        return result(.supported, "The interior face regions are consistently brighter on \(side). This suggests a possible key side; confirm it against the photo before applying a rig.", bounds: bounds, measurements: measurements, direction: direction)
224	    }
