226	    private struct PatchStatistics {
227	        let luminance: Double
228	        let clippedFraction: Double
229	        let opaqueFraction: Double
230	        let count: Int
231	    }
232	
233	    private static func sample(_ image: CGImage, bounds: ReferenceFaceBounds,
234	                               x: Double, y: Double) -> PatchStatistics? {
235	        let rect = CGRect(x: (bounds.x + x * bounds.width) * Double(image.width),
236	                          y: (bounds.y + y * bounds.height) * Double(image.height),
237	                          width: 0.25 * bounds.width * Double(image.width),
238	                          height: 0.15 * bounds.height * Double(image.height))
239	        guard let crop = image.cropping(to: rect), crop.width > 0, crop.height > 0,
240	              let space = CGColorSpace(name: CGColorSpace.sRGB) else { return nil }
241	        let width = min(64, crop.width), height = min(48, crop.height)
242	        // At most 12 KiB per patch; the source decode was bounded before allocation.
243	        var bytes = [UInt8](repeating: 0, count: width * height * 4)
244	        let drawn = bytes.withUnsafeMutableBytes { storage -> Bool in
245	            guard let context = CGContext(data: storage.baseAddress, width: width, height: height,
246	                bitsPerComponent: 8, bytesPerRow: width * 4, space: space,
247	                bitmapInfo: CGBitmapInfo.byteOrder32Big.rawValue | CGImageAlphaInfo.premultipliedLast.rawValue) else { return false }
248	            context.interpolationQuality = .medium
249	            context.draw(crop, in: CGRect(x: 0, y: 0, width: CGFloat(width), height: CGFloat(height)))
250	            return true
251	        }
252	        guard drawn else { return nil }
253	        var values: [Double] = []
254	        values.reserveCapacity(width * height)
255	        var clipped = 0
256	        for index in stride(from: 0, to: bytes.count, by: 4) {
257	            // Only fully opaque pixels have an appearance independent of an
258	            // unspecified background, matching the whole-image tonal summary.
259	            guard bytes[index + 3] == 255 else { continue }
260	            let red = Double(bytes[index]) / 255
261	            let green = Double(bytes[index + 1]) / 255
262	            let blue = Double(bytes[index + 2]) / 255
263	            let encodedLuma = 0.2126 * red + 0.7152 * green + 0.0722 * blue
264	            // One saturated channel can lose usable brightness information even
265	            // when weighted luma is moderate (for example under colored light).
266	            // This checks the rendered SDR values, not the camera's raw sensor.
267	            if encodedLuma <= 0.02 || max(red, max(green, blue)) >= 0.98 { clipped += 1 }
268	            func linear(_ channel: Double) -> Double {
269	                channel <= 0.04045 ? channel / 12.92 : pow((channel + 0.055) / 1.055, 2.4)
270	            }
271	            values.append(0.2126 * linear(red) + 0.7152 * linear(green) + 0.0722 * linear(blue))
272	        }
273	        guard !values.isEmpty else { return nil }
274	        values.sort()
275	        let trim = values.count / 10
276	        let middle = values[trim..<(values.count - trim)]
277	        let luminance = middle.reduce(0, +) / Double(middle.count)
278	        guard luminance.isFinite else { return nil }
279	        return PatchStatistics(luminance: luminance,
280	            clippedFraction: Double(clipped) / Double(values.count),
281	            opaqueFraction: Double(values.count) / Double(width * height), count: values.count)
282	    }
