284	    /// The only shared mutable state. The lock protects registration and cancellation;
285	    /// Vision's cancel() is the sole operation invoked across the worker boundary.
286	    private final class RequestCancellation: @unchecked Sendable {
287	        private let lock = NSLock()
288	        private var request: VNRequest?
289	        private var cancelled = false
290	
291	        func register(_ request: VNRequest) {
292	            lock.lock()
293	            self.request = request
294	            let shouldCancel = cancelled
295	            lock.unlock()
296	            if shouldCancel { request.cancel() }
297	        }
298	
299	        func clear() {
300	            lock.lock()
301	            request = nil
302	            lock.unlock()
303	        }
304	
305	        func cancel() {
306	            lock.lock()
307	            cancelled = true
308	            let activeRequest = request
309	            lock.unlock()
310	            activeRequest?.cancel()
311	        }
312	    }
313	}

