 4	/// Reads only an opened regular file. Callers retain responsibility for any
 5	/// security scope or file-provider coordination surrounding this operation.
 6	enum BoundedFileReader {
 7	    enum ReadError: Error, Equatable {
 8	        case notRegularFile, unreadable, tooLarge
 9	    }
10	
11	    /// Reject a known nonregular final path component before file coordination.
12	    /// This requests metadata only; it does not open or read file contents.
13	    /// Missing or inaccessible metadata is left to the coordinator/provider.
14	    /// Passing this check is not authorization to read: the opened descriptor
15	    /// must still pass the no-follow, type and byte-limit checks below.
16	    static func rejectKnownNonRegularFile(at url: URL) throws {
17	        try Task.checkCancellation()
18	        guard url.isFileURL else { throw ReadError.unreadable }
19	        var info = stat()
20	        let status = url.withUnsafeFileSystemRepresentation { path -> Int32? in
21	            guard let path else { return nil }
22	            return Darwin.lstat(path, &info)
23	        }
24	        guard let status else { throw ReadError.unreadable }
25	        guard status == 0 else { return }
26	        guard info.st_mode & mode_t(S_IFMT) == mode_t(S_IFREG) else {
27	            throw ReadError.notRegularFile
28	        }
29	    }
30	
31	    /// A pathname metadata check cannot prove what a later open will read.
32	    /// O_NOFOLLOW rejects a final symbolic link and O_NONBLOCK prevents a FIFO
33	    /// from blocking before fstat validates the actual opened descriptor.
34	    /// The additional checkpoint may throw to cancel caller-specific work;
35	    /// it cannot suppress cancellation of the current Swift task.
36	    static func read(from url: URL, maximumBytes: Int,
37	                     checkCancellation: () throws -> Void = {}) throws -> Data {
38	        func checkpoint() throws {
39	            try Task.checkCancellation()
40	            try checkCancellation()
41	        }
42	        try checkpoint()
43	        guard url.isFileURL, maximumBytes >= 0, maximumBytes < Int.max else {
44	            throw ReadError.unreadable
45	        }
46	        let descriptor = url.withUnsafeFileSystemRepresentation { path -> Int32 in
47	            guard let path else { errno = EINVAL; return -1 }
48	            return Darwin.open(path, O_RDONLY | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC)
49	        }
50	        guard descriptor >= 0 else {
51	            if errno == ELOOP { throw ReadError.notRegularFile }
52	            throw ReadError.unreadable
53	        }
54	        let handle = FileHandle(fileDescriptor: descriptor, closeOnDealloc: true)
55	        defer { try? handle.close() }
56	        var info = stat()
57	        guard Darwin.fstat(descriptor, &info) == 0, info.st_size >= 0 else {
58	            throw ReadError.unreadable
59	        }
60	        guard info.st_mode & mode_t(S_IFMT) == mode_t(S_IFREG) else {
61	            throw ReadError.notRegularFile
62	        }
63	        guard info.st_size <= maximumBytes else { throw ReadError.tooLarge }
64	        var contents = Data()
65	        contents.reserveCapacity(Int(info.st_size))
66	        while true {
67	            try checkpoint()
68	            // Read at most one extra byte even if the file grows after fstat.
69	            let remaining = maximumBytes + 1 - contents.count
70	            guard remaining > 0 else { throw ReadError.tooLarge }
71	            let chunk: Data?
72	            do { chunk = try handle.read(upToCount: min(64 * 1024, remaining)) }
73	            catch { throw ReadError.unreadable }
74	            guard let chunk, !chunk.isEmpty else { break }
75	            contents.append(chunk)
76	            guard contents.count <= maximumBytes else { throw ReadError.tooLarge }
77	        }
78	        try checkpoint()
79	        return contents
80	    }
81	}

